return (async function(entryUrl, myCheerio, myAxios) {
async function getImgs(url) {
  const response = await myAxios.get(url);
  const $ = myCheerio.load(response.data);

  // 1. 获取第一张图片的src，用于提取基础URL
  const firstImgSrc = $('body > table > tbody > tr:nth-child(3) > td > table > tbody > tr > td > a > img').attr('src');
  if (!firstImgSrc) {
    throw new Error('无法找到第一张图片');
  }

  // 2. 从第一张图片URL中提取基础路径
  const baseUrl = firstImgSrc.replace(/\/\d+\.jpg$/, '/');

  // 3. 获取总页数
  const pageLinks = $('body > table > tbody > tr:nth-child(4) > td > a');
  const totalPages = parseInt($(pageLinks[pageLinks.length - 2]).text(), 10);
  if (Number.isNaN(totalPages)) {
    throw new Error('无法获取总页数');
  }

  // 4. 生成所有图片URL
  const imgUrls = [];
  const {
    protocol
  } = new URL(url);
  for (let i = 1; i <= totalPages; i += 1) {
    const pageNum = i.toString().padStart(3, '0');
    // 移除开头的//，并添加协议
    const imgPath = baseUrl.replace(/^\/\//, '');
    imgUrls.push(`${protocol}//${imgPath}${pageNum}.jpg`);
  }
  return imgUrls;
}
return await getImgs(entryUrl);
})(entryUrl, myCheerio, myAxios);

