return (async function(entryUrl, myCheerio, myAxios) {
/**
 * 将content页url转换为book详情页url
 */
function toBookUrl(contentUrl) {
  // content-xxx-1.html => book-xxx.html
  return contentUrl.replace(/content-(.+?)-\d+\.html$/, 'book-$1.html');
}

/**
 * 获取章节列表
 */
async function getChapters(entryUrl) {
  // 1. 转换为book详情页url
  const bookUrl = toBookUrl(entryUrl);
  // 2. 请求详情页
  const html = (await myAxios.get(bookUrl)).data;
  const $ = myCheerio.load(html);
  // 3. 查找章节列表
  const chapterLinks = [];
  $('body > div > div > div.content-bottom > ul > li > a').each((i, el) => {
    const href = $(el).attr('href');
    const title = $(el).text().trim();
    if (href) {
      // 补全为绝对url
      const absHref = href.startsWith('http') ? href : new URL(href, bookUrl).href;
      chapterLinks.push({
        title,
        href: absHref
      });
    }
  });
  // 4. 判断是否有章节
  if (chapterLinks.length > 0) {
    return chapterLinks;
  }
  // 没有章节，返回默认章节
  return [{
    title: '【默认】',
    href: entryUrl
  }];
}
return await getChapters(entryUrl);
})(entryUrl, myCheerio, myAxios);

