    if (getImgs()) return;

    // 否则轮询等待，最多等5秒
    let count = 0;
    const timer = setInterval(() => {
      if (getImgs() || ++count > 50) {
        clearInterval(timer);
        if (count > 50) resolve([]); // 超时返回空数组
      }
    }, 100);
  });
